/// <summary>
///
/// </summary>
/// <param name="args"></param>
[PostHandlerFor(tableStr(SalesLine), tableMethodStr(SalesLine, insert))]
public static void SalesLine_Post_insert(XppPrePostArgs args)
{
    SalesLine salesLine = args.getThis() as SalesLine;        
    ARGSalesTable argSalesTable;
    SalesTable salesTable = SalesTable::find(salesLine.SalesId);

    select forupdate firstonly argSalesTable
        where argSalesTable.SalesId == salesLine.SalesId;

    real total = (select firstonly sum(SalesQty) from salesLine
         where salesLine.SalesId == salesTable.SalesId).SalesQty;


    if (salesTable)
    {
        ttsbegin;
        argSalesTable.ItemQuantity = total;
        argSalesTable.update();
        ttscommit;
    }
}
